"""Plot WMDP forget-loss landscapes generated by gen_smoothness.py."""

import argparse
import json
import os
import os.path as osp

import matplotlib.pyplot as plt
import numpy as np
import seaborn as sns
from matplotlib.ticker import MaxNLocator

figure_dir = "artifacts/figures"
base_labels = {"Origin", "Base model"}


def panel_rows(models):
    """Group models so each method shares a row with its SAM variant.

    The base model is placed at the start of the first row.
    """
    base, families = [], {}
    for model in models:
        if model["label"] in base_labels:
            base.append({**model, "label": "Base model"})
            continue
        family = model["label"].removesuffix(" + SAM")
        families.setdefault(family, []).append(model)
    rows = list(families.values()) or [[]]
    rows[0] = base + rows[0]
    return rows


def plot_surfaces(results, output, zlim=None):
    coordinates = np.asarray(results["coordinates"])
    x, y = np.meshgrid(coordinates, coordinates)
    layout = panel_rows(results["models"])
    columns = max(len(row) for row in layout)
    rows = len(layout)
    figure = plt.figure(figsize=(4 * columns, 3.5 * rows))
    panels = [
        (row_index * columns + column_index + 1, result)
        for row_index, row in enumerate(layout)
        for column_index, result in enumerate(row)
    ]

    for index, result in panels:
        loss = np.asarray(result["loss"])
        panel_zlim = zlim
        if panel_zlim is None:
            panel_zlim = (float(loss.min()), float(loss.max()))
        if np.isclose(*panel_zlim):
            padding = max(abs(panel_zlim[0]), 1.0) * 0.01
            panel_zlim = (panel_zlim[0] - padding, panel_zlim[1] + padding)

        center = loss[len(loss) // 2, len(loss) // 2]
        span = loss.max() - loss.min()
        title = result["label"]
        if result.get("direction_std") is not None:
            title += f"\nσ={result['direction_std']:g}"
        title += f"\ncenter={center:.3g}  span={span:.3g}"

        axis = figure.add_subplot(rows, columns, index, projection="3d")
        axis.plot_surface(
            x,
            y,
            loss,
            cmap="viridis",
            vmin=panel_zlim[0],
            vmax=panel_zlim[1],
            linewidth=0,
        )
        axis.set(
            title=title,
            xlabel="x",
            ylabel="y",
            zlabel="z",
            xticks=coordinates[::2],
            yticks=coordinates[::2],
            zlim=panel_zlim,
        )
        axis.zaxis.set_major_locator(MaxNLocator(5))

        contour = axis.inset_axes([0.0, 0.68, 0.3, 0.3])
        contour.contour(
            x,
            y,
            loss,
            levels=np.linspace(*panel_zlim, 11),
            cmap="viridis",
            vmin=panel_zlim[0],
            vmax=panel_zlim[1],
        )
        contour.set(xticks=[], yticks=[], xlim=axis.get_xlim(), ylim=axis.get_ylim())

    figure.tight_layout()
    os.makedirs(osp.dirname(output) or ".", exist_ok=True)
    figure.savefig(output, bbox_inches="tight", dpi=200)


def merge_results(paths):
    """Combine independently computed model surfaces on the same grid."""
    combined = None
    for path in paths:
        with open(path) as handle:
            result = json.load(handle)
        if combined is None:
            combined = {"coordinates": result["coordinates"], "models": []}
        elif result["coordinates"] != combined["coordinates"]:
            raise ValueError("cannot combine surfaces with different coordinates")
        for model in result["models"]:
            model = dict(model)
            model.setdefault("direction_std", result.get("direction_std"))
            combined["models"].append(model)
    return combined


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", default=osp.join(figure_dir, "smoothness.pdf"))
    parser.add_argument(
        "--zlim",
        type=float,
        nargs=2,
        metavar=("MIN", "MAX"),
        default=None,
        help="Optional shared z-axis limits (default: automatic per panel)",
    )
    parser.add_argument(
        "inputs",
        nargs="+",
        metavar="JSON",
        help="One or more generated surface files",
    )
    args = parser.parse_args()

    sns.set_theme(style="whitegrid")
    results = merge_results(args.inputs)
    plot_surfaces(results, args.output, args.zlim)


if __name__ == "__main__":
    main()
